-- Latest twelve observed monthly portfolio rows ending in the requested month. Gaps remain missing; do not interpret prior observed row as prior calendar month or sum active_accounts across months.
SELECT * FROM finance.agent_demo_fs.portfolio_monthly_sql WHERE snapshot_id = (SELECT snapshot_id FROM finance.agent_demo_fs.snapshot_metadata_sql WHERE status = 'READY') AND period_key <= CASE WHEN CAST({{period_key}} AS INT) = 0 THEN (SELECT MAX(period_key) FROM finance.agent_demo_fs.portfolio_monthly_sql WHERE snapshot_id = (SELECT snapshot_id FROM finance.agent_demo_fs.snapshot_metadata_sql WHERE status = 'READY')) ELSE CAST({{period_key}} AS INT) END AND EXISTS (SELECT 1 FROM finance.agent_demo_fs.portfolio_monthly_sql WHERE snapshot_id = (SELECT snapshot_id FROM finance.agent_demo_fs.snapshot_metadata_sql WHERE status = 'READY') AND period_key = CASE WHEN CAST({{period_key}} AS INT) = 0 THEN (SELECT MAX(period_key) FROM finance.agent_demo_fs.portfolio_monthly_sql WHERE snapshot_id = (SELECT snapshot_id FROM finance.agent_demo_fs.snapshot_metadata_sql WHERE status = 'READY')) ELSE CAST({{period_key}} AS INT) END) ORDER BY period_key DESC LIMIT 12
